 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    active = [any(v != bg for v in row) for row in grid]
    groups = []
    i = 0
    while i < h:
        if active[i]:
            j = i
            while j + 1 < h and active[j + 1]:
                j += 1
            groups.append((i, j + 1))
            i = j + 1
        else:
            i += 1
    if len(groups) < 2:
        return out
    # The two patterned panels are the largest separated active row groups.
    groups = sorted(groups, key=lambda p: p[1] - p[0], reverse=True)[:2]
    groups.sort()
    (a0, a1), (b0, b1) = groups
    if a1 - a0 != b1 - b0:
        return out
    n = a1 - a0
    best = None
    for dx in range(-w + 1, w):
        score = 0
        denom = 0
        for k in range(n):
            for c in range(w):
                d = c + dx
                if 0 <= d < w:
                    x = grid[a0 + k][c] != bg
                    y = grid[b0 + k][d] != bg
                    score += (x == y)
                    denom += 1
        if denom and (best is None or score / denom > best[0]):
            best = (score / denom, dx)
    if best is None:
        return out
    dx = best[1]
    # Complete the second panel from the first, marking newly supplied pixels.
    for k in range(n):
        for c in range(w):
            d = c + dx
            if 0 <= d < w and grid[a0 + k][c] != bg and grid[b0 + k][d] == bg:
                out[b0 + k][d] = 1
    return out
